∀ {W : ℝ → Breakdown.Space → Breakdown.Space} {q : ℝ → Breakdown.Space → ℝ} {P : ℝ}
  {R : Breakdown.Space ≃ₗᵢ[ℝ] Breakdown.Space},
  Breakdown.FarField.IsSmoothOrbitField W q P R → ∀ (s : ℝ) (y : Breakdown.Space), W (s + P) y = R (W s (R.symm y))

∀ {W : ℝ → Breakdown.Space → Breakdown.Space} {q : ℝ → Breakdown.Space → ℝ} {P : ℝ}
  {R : Breakdown.Space ≃ₗᵢ[ℝ] Breakdown.Space},
  Breakdown.FarField.IsSmoothOrbitField W q P R → ContDiff ℝ ↑⊤ fun z => q z.1 z.2

